def explorar_bfs(grafo, inicio):
    fila = deque([inicio])
    visitados = {inicio}
    while fila:
        atual = fila.popleft()
        for vizinho in grafo[atual]:
            if vizinho not in visitados:
                visitados.add(vizinho)
                fila.append(vizinho)
    return visitados
